package com.lyra.studio; import android.app.Activity; import android.view.WindowManager; import android.webkit.WebSettings; import android.webkit.WebView; import android.webkit.WebViewClient; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Um WebViewer customizado que se adapta ao teclado virtual, evitando que ele cubra o conteudo.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/web.png") @SimpleObject(external = true) public class CustomWebViewer extends AndroidViewComponent { private WebView webView; private Activity activity; public CustomWebViewer(ComponentContainer container) { super(container); this.activity = container.$context(); this.webView = new WebView(activity); /* Configuracoes avancadas simplificadas */ WebSettings webSettings = webView.getSettings(); webSettings.setJavaScriptEnabled(true); webSettings.setDomStorageEnabled(true); webView.setWebViewClient(new WebViewClient()); /* Previne que o teclado cubra o conteudo ajustando o modo da janela */ this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); container.$add(this); } @Override public android.view.View getView() { return webView; } @SimpleFunction(description = "Carrega uma URL no WebViewer customizado.") public void GoToUrl(String url) { webView.loadUrl(url); } @SimpleFunction(description = "Habilita ou desabilita o redimensionamento automatico para o teclado.") public void EnableKeyboardResize(boolean enable) { if(enable) { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } else { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } } }